theorem abs_chebyshevCoeff_le_two_mul {f : ℝ → ℝ} {M : ℝ}
    (hM : ∀ x ∈ Icc (-1 : ℝ) 1, |f x| ≤ M) {k : ℕ} (hk : 0 < k) :
